import html

def render(tpl, **ctx):
    for k, v in ctx.items():
        tpl = tpl.replace("{{ " + k + " }}", html.escape(str(v)))
    return tpl

import html

def render_list(items):
    lines = ["<ul>"]
    for item in items:
        lines.append("<li>" + html.escape(str(item)) + "</li>")
    lines.append("</ul>")
    return "\n".join(lines)
